#include <bits/stdc++.h>
using namespace std;

int main() {
    int A, L;
    if (scanf("%d %d", &A, &L) != 2) return 0;
    int n;
    scanf("%d", &n);

    long long bestArea = LLONG_MAX; // menor área de moldura útil (equivale a menor área não usada)
    int bestId = -1;

    for (int i = 1; i <= n; i++) {
        int x, y;
        scanf("%d %d", &x, &y);

        // A moldura pode ser usada normalmente ou rotacionada
        bool fits = (A <= x && L <= y) || (A <= y && L <= x);

        if (fits) {
            long long area = (long long)x * y;
            // Área não usada = área da moldura - área da foto (constante),
            // então basta minimizar a área da moldura.
            // Usar "<" estrito garante o menor identificador em caso de empate.
            if (area < bestArea) {
                bestArea = area;
                bestId = i;
            }
        }
    }

    printf("%d\n", bestId);
    return 0;
}
